package com.example.payment; import org.springframework.kafka.annotation.KafkaListener; import org.slf4j.Logger; import org.slf4j.LoggerFactory; public class PaymentConsumer {private static final Logger log=LoggerFactory.getLogger(PaymentConsumer.class); @KafkaListener(topics={"payment.created","payment.completed","payment.failed"}) public void consume(String message){log.info("Payment event received {}",message);try{}catch(Exception ex){log.error("Kafka payment event processing failed {}",message);}}}
